import re

_RANGE = re.compile(r'bytes=([0-9]*)-([0-9]*)')


def bounds(header, length):
    """Return inclusive (start, end) for a single byte range, or None if unsatisfiable."""
    if not isinstance(header, str):
        return None
    match = _RANGE.fullmatch(header)
    if match is None:
        return None
    first, last = match.groups()
    if not first and not last:
        return None
    if length == 0:
        return None
    if not first:
        suffix = int(last)
        if suffix == 0:
            return None
        return max(length - suffix, 0), length - 1
    start = int(first)
    if start >= length:
        return None
    if not last:
        return start, length - 1
    end = int(last)
    if end < start:
        return None
    return start, min(end, length - 1)

